function credentialCommands(agentId){
  const short=(agentId||'agent').slice(0,8),name=`auven_${short}`,variable=`AUVEN_AGENT_${short.toUpperCase()}_CREDENTIAL`;
  return {
    codex:`$env:${variable} = Read-Host 'Paste this agent credential'\ncodex mcp add ${name} --url https://auven.xyz/mcp --bearer-token-env-var ${variable}\ncodex mcp get ${name}\ncodex`,
    claude:`$env:${variable} = Read-Host 'Paste this agent credential'\nclaude mcp add-json ${name} '{"type":"http","url":"https://auven.xyz/mcp","headers":{"Authorization":"Bearer \${${variable}}"}}'\nclaude mcp get ${name}\nclaude`,
    api:`$env:${variable} = Read-Host 'Paste this agent credential'\n$headers = @{ Authorization = 'Bearer ' + $env:${variable}; 'Idempotency-Key' = [guid]::NewGuid().ToString() }\nInvoke-RestMethod -Method Post -Uri https://auven.xyz/api/gateway/chat -Headers $headers -ContentType 'application/json' -Body '{"messages":[{"role":"user","content":"Hello from AUVEN"}],"max_tokens":100}'`
  };
}
